import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.A2C2PdWC.js";var i=JSON.parse(`{"title":"Prefer VoidZero Crates for JavaScript Tooling","description":"","frontmatter":{"id":"policy.0001","title":"Prefer VoidZero Crates for JavaScript Tooling","status":"active","established-by":"proposal.0001","supersedes":[]},"headers":[],"relativePath":"policies/0001-prefer-voidzero-crates.md","filePath":"policies/0001-prefer-voidzero-crates.md"}`),a={name:`policies/0001-prefer-voidzero-crates.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="prefer-voidzero-crates-for-javascript-tooling" tabindex="-1">Prefer VoidZero Crates for JavaScript Tooling <a class="header-anchor" href="#prefer-voidzero-crates-for-javascript-tooling" aria-label="Permalink to “Prefer VoidZero Crates for JavaScript Tooling”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Bento reuses two upstream ecosystems that overlap: Deno&#39;s runtime crates, which bring their own SWC-based parsing and Deno&#39;s resolver, and VoidZero&#39;s toolchain (Oxc, <code>oxc_resolver</code>, Rolldown). This policy settles which one Bento&#39;s own code builds on whenever both could do the job. Bento then has one parser, one transformer, and one resolver family that behave identically in the runtime and in future tooling.</p><h2 id="the-rule" tabindex="-1">The rule <a class="header-anchor" href="#the-rule" aria-label="Permalink to “The rule”">​</a></h2><p>Bento code must use VoidZero crates for parsing, transformation, source maps, minification, module resolution, and bundling wherever they provide the capability, and must not add Deno- or SWC-based crates for those roles.</p><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to “Why this exists”">​</a></h2><p>The first runtime design adapted Deno&#39;s standalone runtime wholesale, which would have pulled in <code>deno_ast</code> (SWC) to analyze CommonJS exports and kept Deno&#39;s resolver for every import. Meanwhile, the transformer already used Oxc. Every application module would have been parsed by two different parsers whose syntax support, error messages, and edge cases differ. tsconfig would have been read by a different implementation than the one Oxc-based tools use. Each duplicate is another place where the runtime and future Bento tooling can disagree about the same source file, and another dependency stack to upgrade.</p><h2 id="what-it-applies-to" tabindex="-1">What it applies to <a class="header-anchor" href="#what-it-applies-to" aria-label="Permalink to “What it applies to”">​</a></h2><ul><li>Applies to: dependencies that Bento crates declare, and the code paths Bento owns: TypeScript and JSX transformation, tsconfig loading, CommonJS/ESM export analysis, ESM import resolution, source maps, and any future minifier, bundler, or development server.</li><li>Does not apply to: crates that a reused upstream component requires internally. For example, <code>deno_node</code> links <code>deno_ast</code>, and its CommonJS <code>require</code> and CJS-to-ESM translation are built on <code>node_resolver</code>. Those stay until Bento owns that component. It also does not apply to the application&#39;s own npm dependencies (a fixture&#39;s <code>oxc-transform</code>, <code>lightningcss</code>, or <code>typescript</code> packages) or to capabilities no VoidZero crate offers, such as CSS (Lightning CSS) or the JavaScript engine itself.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Tier: check, with prose for role choices.</li><li>Mechanism: <code>vp run check</code> runs <code>node tools/crate-dependencies.ts</code>. It fails when any workspace crate declares a direct dependency on <code>deno_ast</code>, <code>deno_graph</code>, <code>dprint-swc-ext</code>, or any <code>swc</code>/<code>swc_*</code> package, under any dependency kind or rename.</li><li>Prose justification: the check catches the SWC stack, which has a VoidZero replacement for every role Bento owns. Whether a Deno crate is required or replaceable depends on what it does. A crate like <code>node_resolver</code> is legitimate when <code>deno_node</code> requires it, so reviewers judge Deno crates against this policy rather than a denylist.</li></ul><h2 id="how-to-comply" tabindex="-1">How to comply <a class="header-anchor" href="#how-to-comply" aria-label="Permalink to “How to comply”">​</a></h2><ol><li>Before adding a dependency for a parsing, transformation, resolution, source-map, minification, or bundling role, look for the VoidZero crate that provides it (<code>oxc</code>, <code>oxc_resolver</code>, <code>oxc_sourcemap</code>, Rolldown) and use that.</li><li>If only a Deno or SWC crate can fill the role, record why in the dependent crate&#39;s <code>Cargo.toml</code> next to the dependency. If the check rejects it, change this policy through a proposal rather than working around the check.</li><li>Run <code>vp run check</code> before submitting.</li></ol><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Proposal</th></tr></thead><tbody><tr><td>2026-10-10</td><td>Established this policy.</td><td>proposal.0001</td></tr></tbody></table>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};